import com.godjiismp.skills.Skills;import com.godjiismp.skills.SkillsConfig;import net.minecraft.core.component.DataComponents;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.food.FoodProperties;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.Unique;import org.spongepowered.asm.mixin.injection.At;import org.spongepowered.asm.mixin.injection.Inject;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(LivingEntity.class) public abstract class SkillFoodMixin {@Unique private ItemStack godjiismp$foodBeforeUse=ItemStack.EMPTY;@Inject(method="completeUsingItem",at=@At("HEAD")) private void godjiismp$rememberFood(CallbackInfo ci){LivingEntity self=(LivingEntity)(Object)this;if(self instanceof ServerPlayer)godjiismp$foodBeforeUse=self.getUseItem().copy();}@Inject(method="completeUsingItem",at=@At("TAIL")) private void godjiismp$bonusSaturation(CallbackInfo ci){LivingEntity self=(LivingEntity)(Object)this;if(self instanceof ServerPlayer player&&!godjiismp$foodBeforeUse.isEmpty()){FoodProperties food=godjiismp$foodBeforeUse.get(DataComponents.FOOD);int level=Skills.level(player,3);if(food!=null&&level>0){float extra=food.nutrition()*food.saturation()*2.0f*(float)(SkillsConfig.saturationPerLevel*level);var data=player.getFoodData();data.setSaturation(Math.min(data.getFoodLevel(),data.getSaturationLevel()+extra));}}godjiismp$foodBeforeUse=ItemStack.EMPTY;}}
